      "pattern": "^r[0-9]+$",
      "type": "string"
    },
    "semantic_ref": {
      "description": "Anchor into a declared anonymous J/C handle. It is not a pi graph-node ID and never appears directly at route/order/sharing endpoints.",
      "pattern": "^(t|n|a|d|e|q|b|s|v|p|c|x)[0-9]+$",
      "type": "string"
