import json
from collections import defaultdict, deque
p='/output/candidate.json'; q='/work/previous_candidate.json'
with open(p) as f: a=json.load(f)
with open(q) as f: old=json.load(f)
assert list(sorted(a.keys())) == ['c','j','pi','schema']
assert a['j']==old['j'], 'fresh repair must preserve J'
assert a['c']==old['c'], 'fresh repair must preserve C'
ids=[x['id'] for x in a['pi']['instances']]
assert ids==[f'i{k}' for k in range(len(ids))], ids
S=set(ids)
for r in a['pi']['routes']:
    assert r['source'] in S and r['target'] in S and r['source']!=r['target']
for o in a['pi']['order']:
    assert o['before'] in S and o['after'] in S and o['before']!=o['after']
route_pairs={(r['source'],r['target']) for r in a['pi']['routes']}
for sh in a['pi']['sharing']:
    assert all((sh['source'],c) in route_pairs for c in sh['consumers'])
for ref in a['pi']['refinements']:
    assert ref['instance'] in S
# Route and explicit order constraints must be acyclic.
g=defaultdict(set); indeg={x:0 for x in S}
for r in a['pi']['routes']:
    g[r['source']].add(r['target'])
for o in a['pi']['order']:
    g[o['before']].add(o['after'])
for u in S:
    for v in g[u]: indeg[v]+=1
d=deque(sorted((x for x in S if indeg[x]==0),key=lambda s:int(s[1:])))
seen=[]
while d:
    u=d.popleft(); seen.append(u)
    for v in sorted(g[u],key=lambda s:int(s[1:])):
        indeg[v]-=1
        if indeg[v]==0: d.append(v)
assert len(seen)==len(S), 'cycle in pi constraints'
print('focused repair invariants: PASS')
print('affected graph:')
for x in a['pi']['instances'][6:13]: print(x)
for r in a['pi']['routes']:
    if r['source'] in {'i6','i7','i8','i9','i10','i11','i12'} or r['target'] in {'i9','i10','i11','i12'}:
        print(r)
